import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
from hts_close import close_voice
lines = [
 "क्या आप या आपके घर में कोई ज़ोर से खर्राटे लेता है? रात में सांस रुकती है, और दिन भर नींद और थकान रहती है? यह स्लीप एपनिया हो सकता है. आखिर तक देखिए.",
 "स्लीप एपनिया में, सोते समय गले का रास्ता बार बार बंद हो जाता है. सांस दस सेकंड या उससे ज़्यादा रुक जाती है, फिर व्यक्ति हांफ कर या झटके से सांस लेता है. अक्सर व्यक्ति को खुद पता नहीं चलता, पास सोने वाले को पता चलता है.",
 "एम्स दिल्ली के एक अध्ययन के अनुसार, भारत में लगभग ग्यारह प्रतिशत वयस्कों को यह समस्या हो सकती है. यानी लगभग दस करोड़ लोग. और ज़्यादातर लोगों को पता ही नहीं.",
 "इसके लक्षण क्या हैं? ज़ोर के खर्राटे, बीच में सांस रुकना या दम घुटने जैसी आवाज़, सुबह सिर दर्द, दिन में बहुत नींद, ध्यान न लगना, और चिड़चिड़ापन. लेकिन ध्यान दें, हर खर्राटे लेने वाले को स्लीप एपनिया नहीं होता.",
 "किसे ज़्यादा खतरा है? ज़्यादा वज़न या मोटी गर्दन, बढ़ती उम्र, परिवार में किसी को यह समस्या, शराब और धूम्रपान, बड़े टॉन्सिल, और पीठ के बल सोना.",
 "इलाज न हो तो यह हाई ब्लड प्रेशर, दिल की बीमारी, धड़कन की गड़बड़ी, और स्ट्रोक का खतरा बढ़ा सकता है. और दिन में नींद आने से, गाड़ी चलाते समय दुर्घटना का खतरा भी बढ़ता है.",
 "इसकी जांच है स्लीप स्टडी, यानी पॉलीसोम्नोग्राफी. रात को सोते समय शरीर पर सेंसर लगाए जाते हैं. ये सांस, खून में ऑक्सीजन, दिल की धड़कन, दिमाग की तरंगें, और शरीर की हरकत रिकॉर्ड करते हैं. यह दर्द रहित है. कुछ लोगों की जांच घर पर भी हो सकती है. यह डॉक्टर तय करते हैं.",
 "जांच वाले दिन चाय, कॉफी और शराब से बचें. नींद की दवा सिर्फ डॉक्टर से पूछ कर लें. रिपोर्ट में ए एच आई होता है, यानी हर घंटे सांस कितनी बार रुकी या कम हुई. पांच से कम सामान्य, पांच से चौदह हल्का, पंद्रह से उनतीस मध्यम, और तीस या ज़्यादा गंभीर.",
 "अच्छी खबर, इसका इलाज है. वज़न कम करना, शराब और धूम्रपान छोड़ना, और करवट लेकर सोना. ज़रूरत हो तो डॉक्टर सी पैप मशीन की सलाह देते हैं, जो मास्क से हल्की हवा देकर, गले का रास्ता खुला रखती है.",
 close_voice("क्या आपके घर में कोई ज़ोर से खर्राटे लेता है?"),
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/slpr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/slp_{i}.wav"],check=True); f=f"/tmp/slp_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/slp_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
